import { readFileSync } from "node:fs";
import path from "node:path";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import { getDb, getPool } from "./db";
import { log } from "./log";

/**
 * Drizzle-based migration runner. Replaces the hand-rolled runner that used
 * to live in db.ts (tracked in a `schema_migrations` table).
 *
 * Migration files live in drizzle/ (generated by `drizzle-kit generate`
 * from src/lib/schema.ts) and are tracked by drizzle's own migrator in
 * `drizzle.__drizzle_migrations`. The migrator applies any journal entry
 * not yet recorded there.
 *
 * Prod was reset (wiped) as part of the drizzle cutover — there is no
 * legacy-schema detection here on purpose. Fresh DBs just run the full
 * baseline.
 */

const MIGRATIONS_FOLDER = path.join(process.cwd(), "drizzle");

interface JournalEntry {
  idx: number;
  when: number;
  tag: string;
  breakpoints: boolean;
}

function readJournal(): JournalEntry[] {
  const raw = readFileSync(path.join(MIGRATIONS_FOLDER, "meta", "_journal.json"), "utf-8");
  return (JSON.parse(raw) as { entries: JournalEntry[] }).entries;
}

export async function runMigrations(): Promise<void> {
  const entries = readJournal();

  // drizzle's migrator is silent; log per-entry apply/skip based on the
  // last applied created_at so boot logs keep the old migration.apply shape.
  let pending = entries;
  try {
    const res = await getPool().query<{ created_at: string | null }>(
      "SELECT max(created_at)::text AS created_at FROM drizzle.__drizzle_migrations",
    );
    const last = res.rows[0]?.created_at ? Number(res.rows[0].created_at) : null;
    if (last !== null) pending = entries.filter((e) => e.when > last);
  } catch {
    // drizzle schema/table doesn't exist yet — everything is pending.
  }
  for (const e of pending) {
    log({ event: "migration.apply", tag: e.tag });
  }
  if (pending.length === 0) {
    log({ event: "migration.up_to_date" });
  }
  await migrate(getDb(), { migrationsFolder: MIGRATIONS_FOLDER });
}

/**
 * Ground-truth readiness check: compares the number of applied rows in
 * drizzle.__drizzle_migrations against the number of entries in
 * drizzle/meta/_journal.json, rather than trusting in-process state. An
 * in-memory "migrations done" flag was tried before and removed — Next's
 * standalone/Turbopack build can bundle Route Handlers and the
 * instrumentation hook into separate chunks, each getting its own
 * module-scope copy, so a flag set by runMigrations() (running inside the
 * instrumentation bundle) was never visible to the readiness route's
 * bundle. Querying the DB + reading the journal at runtime sidesteps that
 * entirely. Fails closed — a DB error (e.g. drizzle schema missing) means
 * "not ready".
 */
export async function migrationsAppliedInDb(): Promise<boolean> {
  const expected = readJournal().length;
  if (expected === 0) return true;
  const res = await getPool().query<{ n: number }>(
    "SELECT count(*)::int AS n FROM drizzle.__drizzle_migrations",
  );
  return (res.rows[0]?.n ?? 0) >= expected;
}
